def solve():
    N, K, X = map(int, input().split())
    A = list(map(int, input().split()))
    A = [i << 30 for i in A]

    def calc(mid):
        cnt = 0
        for i in A:
            c = 1
            while i > mid:
                c *= 2
                i //= 2
            cnt += c - 1
            cnt = min(cnt, K)
        return cnt

    ok, ng = 1 << 60, 0
    while abs(ok - ng) > 1:
        mid = (ok + ng) // 2
        if calc(mid) < K:
            ok = mid
        else:
            ng = mid

    B = []
    rem = K - calc(ok)

    for i in A:
        c = 1
        while i > ok:
            c *= 2
            i //= 2
        if i != ok:
            B.append((i, c))
        else:
            c1 = min(rem, c)
            c2 = c - c1
            B.append((i // 2, 2 * c1))
            B.append((i, c2))
            rem -= c1

    B.sort(reverse=True)
    for v, c in B:
        X -= c
        if X <= 0:
            print("{:.20f}".format(v / (1 << 30)))
            return


for _ in range(int(input())):
    solve()

#include <iostream>
#include <iomanip>
#include <queue>

int main() {
    using namespace std;
    cout << setprecision(15);
    unsigned T;
    cin >> T;
    for (unsigned t{}; t < T; ++t) []{
        unsigned N, K, X;
        cin >> N >> K >> X;
        // (長さ, 本数) を管理する priority_queue
        priority_queue<pair<double, unsigned>> pq;
        for (unsigned i{}; i < N; ++i) {
            double a;
            cin >> a;
            pq.emplace(a, 1); // はじめ、長さ a が 1 本ある（重複があっても気にしない）
        }

        // 操作を行う
        while (K) {
            const auto [a, count]{pq.top()};
            pq.pop();
            if (K <= count) { // ここで終わりなら
                pq.emplace(a / 2, K * 2); // 途中まで操作して
                pq.emplace(a, count - K); // いくつか残る
                K = 0;
                break;
            } // そうでなければ
            pq.emplace(a / 2, count * 2); // 全部半分になる
            K -= count;
        }

        // 大きいほうから X 番目を求める
        while (X) {
            const auto [a, count]{pq.top()};
            pq.pop();
            if (X <= count) {
                cout << a << '\n';
                break;
            }
            X -= count;
        }
    }();
    return 0;
}
